using System;using System.IO;using System.Numerics;using System.Text;
namespace SoulboundLegends.NetworkTransport;
public sealed class NetworkWriter:IDisposable{readonly MemoryStream s;public NetworkWriter(int cap=256){s=new MemoryStream(cap);}public void Write(byte v)=>s.WriteByte(v);public void Write(bool v)=>s.WriteByte(v?(byte)1:(byte)0);public void Write(ushort v)=>Write(BitConverter.GetBytes(v));public void Write(short v)=>Write(BitConverter.GetBytes(v));public void Write(uint v)=>Write(BitConverter.GetBytes(v));public void Write(int v)=>Write(BitConverter.GetBytes(v));public void Write(ulong v)=>Write(BitConverter.GetBytes(v));public void Write(long v)=>Write(BitConverter.GetBytes(v));public void Write(float v)=>Write(BitConverter.GetBytes(v));public void Write(double v)=>Write(BitConverter.GetBytes(v));public void Write(Guid v)=>Write(v.ToByteArray());public void Write(string v){var b=Encoding.UTF8.GetBytes(v??"");Write7((uint)b.Length);Write(b);}public void Write(byte[] b){s.Write(b,0,b.Length);}public void Write(ReadOnlySpan<byte>b){s.Write(b);}public void Write(Vector3 v){Write(v.X);Write(v.Y);Write(v.Z);}public void Write(Quaternion q){Write(q.X);Write(q.Y);Write(q.Z);Write(q.W);}public void Write7(uint v){while(v>=128){Write((byte)(v|128));v>>=7;}Write((byte)v);}public byte[] ToArray()=>s.ToArray();public void Dispose()=>s.Dispose();}
public sealed class NetworkReader{readonly byte[] b;int p;public NetworkReader(byte[] bytes){b=bytes;}void Need(int n){if(n<0||p+n>b.Length)throw new InvalidDataException("Network payload truncated");}public byte ReadByte(){Need(1);return b[p++];}public bool ReadBool()=>ReadByte()!=0;public ushort ReadUShort(){Need(2);var v=BitConverter.ToUInt16(b,p);p+=2;return v;}public short ReadShort(){Need(2);var v=BitConverter.ToInt16(b,p);p+=2;return v;}public uint ReadUInt(){Need(4);var v=BitConverter.ToUInt32(b,p);p+=4;return v;}public int ReadInt(){Need(4);var v=BitConverter.ToInt32(b,p);p+=4;return v;}public ulong ReadULong(){Need(8);var v=BitConverter.ToUInt64(b,p);p+=8;return v;}public long ReadLong(){Need(8);var v=BitConverter.ToInt64(b,p);p+=8;return v;}public float ReadFloat(){Need(4);var v=BitConverter.ToSingle(b,p);p+=4;return v;}public double ReadDouble(){Need(8);var v=BitConverter.ToDouble(b,p);p+=8;return v;}public Guid ReadGuid(){Need(16);var a=new byte[16];Buffer.BlockCopy(b,p,a,0,16);p+=16;return new Guid(a);}public string ReadString(int max=4096){var n=Read7();if(n>max)throw new InvalidDataException("String too large");Need((int)n);var v=System.Text.Encoding.UTF8.GetString(b,p,(int)n);p+=(int)n;return v;}public Vector3 ReadVector3()=>new(ReadFloat(),ReadFloat(),ReadFloat());public Quaternion ReadQuaternion()=>new(ReadFloat(),ReadFloat(),ReadFloat(),ReadFloat());uint Read7(){uint r=0;int sh=0;while(sh<=28){var x=ReadByte();r|=(uint)(x&127)<<sh;if((x&128)==0)return r;sh+=7;}throw new InvalidDataException("Invalid varint");}}
